@push('scripts')<script>document.addEventListener('DOMContentLoaded',function(){const type=document.getElementById('accountType'), personal=document.getElementById('personalFields'), patient=document.getElementById('patientFields');function toggle(){const isPatient=type.value==='patient';personal.classList.toggle('d-none',isPatient);patient.classList.toggle('d-none',!isPatient);personal.querySelectorAll('input,select').forEach(e=>e.disabled=isPatient);patient.querySelectorAll('input,select').forEach(e=>e.disabled=!isPatient)}type.addEventListener('change',toggle);toggle();});</script>@endpush
